import React, { useState, useEffect } from 'react';
import { useBrowserHijacking } from '../hooks/useBrowserHijacking';

interface FakeScanProps {
  onComplete: () => void;
  onLearnMore: () => void;
}

const FakeScan: React.FC<FakeScanProps> = ({ onComplete, onLearnMore }) => {
  const [scanLines, setScanLines] = useState<string[]>([]);
  const [currentLine, setCurrentLine] = useState(0);
  const [scanComplete, setScanComplete] = useState(false);

  // Use real scareware browser hijacking techniques
  const { blockedAttempts, isFullscreen } = useBrowserHijacking({
    forceFullscreen: true,
    preventEscape: true,
    preventTabSwitch: true,
    preventMouseEvents: true,
    preventWindowControl: true
  });

  const scanOutput = [
    "Microsoft Defender - System Scan",
    "==================================",
    "Initializing scan engine...",
    "Scanning system files...",
    "Checking registry entries...",
    "Analyzing startup programs...",
    "Scanning browser data...",
    "Checking network connections...",
    "",
    "⚠️  THREAT DETECTED: Trojan.Win32.Malware",
    "⚠️  THREAT DETECTED: Virus.Win32.Stealer",
    "⚠️  THREAT DETECTED: Ransomware.Win32.Crypto",
    "⚠️  THREAT DETECTED: Spyware.Win32.Keylogger",
    "⚠️  THREAT DETECTED: Adware.Win32.Popup",
    "",
    "Total threats found: 47",
    "Critical threats: 12",
    "High risk threats: 23",
    "Medium risk threats: 12",
    "",
    "⚠️  SYSTEM COMPROMISED ⚠️",
    "Your personal data is at risk!",
    "Banking information may be stolen!",
    "Passwords have been compromised!",
    "",
    "SIMULATION MODE: This is a safe educational demonstration",
    "Real threats would require immediate professional assistance",
    "",
    "Scan completed at: " + new Date().toLocaleTimeString()
  ];

  useEffect(() => {
    if (currentLine < scanOutput.length) {
      const timer = setTimeout(() => {
        setScanLines(prev => [...prev, scanOutput[currentLine]]);
        setCurrentLine(prev => prev + 1);
      }, 150); // Faster typing for more urgency

      return () => clearTimeout(timer);
    } else if (!scanComplete) {
      setScanComplete(true);
      // Real scareware technique: Keep the scan "running" to create urgency
      setTimeout(() => {
        setScanLines(prev => [...prev, "⚠️  CRITICAL: System files corrupted!"]);
        setTimeout(() => {
          setScanLines(prev => [...prev, "⚠️  WARNING: Personal data being transmitted!"]);
          setTimeout(() => {
            setScanLines(prev => [...prev, "⚠️  ALERT: Banking information compromised!"]);
            setTimeout(onComplete, 1000);
          }, 1000);
        }, 1000);
      }, 1000);
    }
  }, [currentLine, scanComplete, onComplete]);

  const handleLearnMore = () => {
    onLearnMore();
  };

  return (
    <div className="simulation-content">
      <div className="scareware-alert">
        <h2>🚨 SYSTEM SCAN IN PROGRESS</h2>
        <p>Multiple threats detected! Your system is compromised!</p>
        <p style={{ fontSize: '0.9rem', marginTop: '1rem' }}>
          <strong>SIMULATION MODE:</strong> This is a safe educational demonstration
        </p>
      </div>

      <div className="fake-scan">
        {scanLines.map((line, index) => (
          <div key={index} className="fake-scan-line">
            {line}
          </div>
        ))}
        {scanComplete && (
          <div className="fake-scan-line" style={{ color: '#ff4757', fontWeight: 'bold' }}>
            {'>>> SCAN COMPLETE - SYSTEM AT RISK <<<'}
          </div>
        )}
      </div>

      <div style={{ marginTop: '2rem', textAlign: 'center' }}>
        <button className="button button-success" onClick={handleLearnMore}>
          Learn About Real Scareware (Safe)
        </button>
      </div>

      <div className="escape-info">
        <h3>📚 What's Happening</h3>
        <p>
          This simulates a fake virus scan that real scareware uses to create urgency and fear. 
          Notice how it:
        </p>
        <ul className="escape-steps">
          <li>Shows technical-looking output to appear legitimate</li>
          <li>Claims to find many threats to create panic</li>
          <li>Uses official-sounding names like "Microsoft Defender"</li>
          <li>Makes urgent claims about data theft</li>
          <li>Creates a false sense of immediate danger</li>
        </ul>
        <p style={{ marginTop: '1rem', fontSize: '0.9rem' }}>
          <strong>Remember:</strong> Real security software doesn't create panic or demand immediate payment.
        </p>
      </div>
    </div>
  );
};

export default FakeScan;
